CREATE TABLE "SyncMutation"("id" UUID NOT NULL,"companyId" UUID NOT NULL,"userId" UUID NOT NULL,"payload" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SyncMutation_pkey" PRIMARY KEY("id")); ALTER TABLE "SyncMutation" ENABLE ROW LEVEL SECURITY; ALTER TABLE "SyncMutation" FORCE ROW LEVEL SECURITY; CREATE POLICY "sync_tenant" ON "SyncMutation" FOR ALL USING("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid);